import { useEffect } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

import Navbar from "@/components/Navbar";
import Hero from "@/components/home/Hero";
import Films from "@/components/home/Films";
import Featured from "@/components/home/Featured";
import About from "@/components/home/About";
import Footer from "@/components/Footer";

gsap.registerPlugin(ScrollTrigger);

const Index = () => {
  useEffect(() => {
    gsap.to(".hero-section", {
      yPercent: 20,
      ease: "none",
      scrollTrigger: {
        trigger: ".page-container",
        start: "top top",
        end: "bottom bottom",
        scrub: true,
      },
    });

    gsap.to(".films-section", {
      yPercent: -40,
      ease: "none",
      scrollTrigger: {
        trigger: ".page-container",
        start: "top top",
        end: "bottom bottom",
        scrub: 1.5,
      },
    });

    gsap.to(".content-section", {
      yPercent: -40,
      ease: "none",
      scrollTrigger: {
        trigger: ".page-container",
        start: "top top",
        end: "bottom bottom",
        scrub: 1.5,
      },
    });

  }, []);


  return (
    <main className="w-full flex flex-col items-center page-container">
      <Navbar />

      {/* Hero */}
      <section className="relative hero-section w-full h-screen flex items-center justify-center">
        <Hero />
      </section>

      {/* Content */}
      <section className="relative w-full films-section">
        <Films />
      </section>

      <section className="relative w-full content-section">
        <Featured />
        <About />
        <Footer />
      </section>
    </main>
  );
};

